#include <iostream>
#include <queue>
#include <vector>

struct Pair {
    int location;
    int dist;
};

int main() {
    int n, m;
    std::cin >> n >> m;

    if (n >= m) {
        std::cout << n - m << '\n';
    } else {
        std::vector<bool> visited(m + 2, false);
        std::queue<Pair> queue;

        queue.push({n, 0});
        visited[n] = true;

        int ans = 0;

        while (!queue.empty()) {
            Pair tmp = queue.front();
            queue.pop();

            if (tmp.location == m) {
                ans = tmp.dist;
                break;
            }

            if (tmp.location * 2 <= m + 1 && !visited[tmp.location * 2]) {
                queue.push({tmp.location * 2, tmp.dist + 1});
                visited[tmp.location * 2] = true;
            }

            if (tmp.location - 1 >= 0 && !visited[tmp.location - 1]) {
                queue.push({tmp.location - 1, tmp.dist + 1});
                visited[tmp.location - 1] = true;
            }
        }

        std::cout << ans << '\n';
    }

    return 0;
}

